		tldr_p2: "이 감사는 두 위원회 지도를 똑같은 방식으로, 공식 Elections Alberta 파일로 컴퓨터가 그린 중립 지도 1,010,000개와 비교해 시험했습니다. 다수 안은 중립적 작성이 일상적으로 만들어 내는 지도처럼 보입니다. 사전 등록된 모든 시험을 통과합니다. 소수 안은 다섯 가지 구조적 시험 중 네 가지를 넘으며, 50/50 동률 득표에서 1,010,000개의 중립 지도 중 그만큼 많은 의석을 주는 지도는 약 69개뿐입니다. 중립 절차가 그 전반적 공정성 특성을 만들어 낼 확률은 약 568,000분의 1로 계산됩니다. 그리고 이 수치는 정밀한 추정치가 아니라 일부러 신중하게 잡은 상한입니다. 한 척도, 즉 효율성 격차는 감사가 미리 정한 선 바로 아래에 떨어졌으며, 미달로 보고됩니다.",
