			p1: "두 가지 문제가 앨버타 지도에 대한 모든 감사를 필요 이상으로 어렵게 만듭니다. 첫째, 이제 전체 표의 약 절반이 선거일 전에 들어오는데, Elections Alberta는 그 표를 투표 구역이 아니라 선거구 단위로 보고합니다. 그래서 2023년에 던져진 NDP와 UCP 표 약 395,000표는 지도 위에 놓을 수 없습니다. 둘째, 위원회는 지도가 효력을 갖게 될 즈음이면 이미 몇 년 묵은 인구조사 자료로 지도를 그립니다. 두 문제 모두 고칠 수 있습니다. <a href=\"__BASE__/fixes\">제안 페이지</a>가 그 방법을 설명합니다."
