			p1: "표지 지도는 이 감사에서 가장 좋은 한 장의 이미지입니다. 다음은 그것을 읽는 방법입니다.",
			p2: "앨버타는 4,765개의 투표 구역(Voting Areas)으로 나뉘어 있습니다 — Elections Alberta가 투표소 투표지를 집계하는 데 사용하는 작은 지리적 구역입니다. 각 구역은 2023년에 그 안의 사람들이 실제로 투표한 양상으로 채색됩니다. NDP 표가 집중된 곳은 주황, UCP 표가 집중된 곳은 파랑. 그러나 많은 사람이 사는 곳에서만 색이 진하고 채도가 높아집니다. 수백 제곱킬로미터의 공원이나 농지를 덮는 투표 구역은 옅게 — 거의 보이지 않게 — 남습니다. 지도는 사람이 있는 곳에서 환해지고 없는 곳에서 사라집니다.",
			p3: "이는 당신이 선거의 밤에 보는 앨버타와 매우 다릅니다. 대부분의 선거 지도는 승자에 따라 선거구 전체를 단색의 파랑이나 주황으로 칠합니다. 농촌 선거구는 지리적으로 크고 UCP가 대부분을 이기기 때문에, 선거의 밤 앨버타는 에드먼턴과 캘거리에 작은 주황 주머니가 있는 파란 벽처럼 보입니다. 표지 지도는 동일한 표와 동일한 지리를 사용하지만 — 사람들이 실제로 사는 곳에 가중치를 두어 보여줍니다. 나타나는 것은 인구 대부분이 도시의 빽빽한 호에 집중되어 있는 주이며, 이 도시들은 보통 그것들을 대표하는 농촌 지도와는 매우 다르게 투표합니다.",
