			p1: "저는 마운트로열대학교의 학생입니다. 이 연구는 혼자 했습니다 — 학과 과제로 할당된 것이 아니며 대학교가 의뢰하지도 않았습니다. 제 견해는 제 자신의 것이며 대학교를 대표하지 않습니다. 저는 약 27년에 걸쳐 선거가 있을 때마다 Elections Alberta의 계약직 선거 관리 요원으로 일하며 선거 당일 투표 관리를 맡았습니다. 현재는 계약 중이 아니며, 마지막으로 일한 것은 최근에 치러진 한 선거에서였습니다. 그 밖에 Elections Alberta에 고용된 적은 없으며, 이 일 외에는 그 기관의 업무에 대해 아는 바가 없습니다. 이 감사의 어떤 내용도 그 일에서 나온 것이 아니며, 모든 입력 자료는 공개 자료입니다. 이 연구는 Elections Alberta가 아닌 저 자신의 것이며, 그 기관을 대변하지 않습니다. 저는 위원회와 관련이 없습니다. 저는 성인이 된 이후 앨버타의 보수 성향과 진보 성향 주 정당 모두에 투표하고 후원금을 낸 적이 있습니다.",
