			conditions_intro: "모든 발견은 특정한 반증 조건에 사전 약속되어 있습니다. 아래 조건 중 어느 것이라도 실현되면, 그것이 명명하는 발견은 30일 이내에 공개적으로 철회됩니다. 전반적인 방향적 결론 — 소수 지도가 여러 독립된 시험에서 중립 범위 밖에 위치한다는 것 — 은 방법론에 사전 약속된 복합 조건에 따라 철회됩니다. 즉 여섯 개의 독립된 구조적 차원 중 최소 세 개가 방향을 역전할 경우입니다.",
